213→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
214→  function blockCartButtonsInitial() {
215→    var ATC_SELECTORS = [
216→      'button[name="add"]',
217→      '.product-form__submit',
218→      '[data-product-add]',
219→      '.btn--add-to-cart',
220→      '.product-form button[type="submit"]',
221→      'button.shopify-payment-button__button',
222→      '.shopify-payment-button button',
223→      'button.product-form__cart-submit'
224→    ].join(',');
225→
226→    function doBlock() {
227→      try {
228→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
229→        atcBtns.forEach(function(b) {
230→          if (!b.closest('[data-zcc-widget]')) {
231→            if (!b.getAttribute('data-zcc-blocked')) {
232→              b.setAttribute('data-zcc-orig-title', b.title || '');
233→            }
234→            b.disabled = true;
235→            b.style.opacity = '0.5';
236→            b.title = 'Please check ZIP code availability first';
237→            b.setAttribute('data-zcc-blocked', 'true');
238→          }
239→        });
240→      } catch(e) {}
241→    }
242→
243→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
244→    doBlock();
245→    setTimeout(doBlock, 500);
246→    setTimeout(doBlock, 1500);
247→
248→    // MutationObserver for dynamic payment buttons
249→    if (typeof MutationObserver !== 'undefined') {
250→      var observer = new MutationObserver(function() { doBlock(); });
251→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
252→      if (form) {
253→        observer.observe(form, { childList: true, subtree: true });
254→        setTimeout(function() { observer.disconnect(); }, 10000);
255→      }
256→    }
257→  }
